<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';import {useRouter} from 'vue-router';import UiIcon from './UiIcon.vue'
const modal=ref<HTMLDialogElement|null>(null),query=ref(''),router=useRouter();function open(){modal.value?.showModal()}function submit(){modal.value?.close();void router.push({path:'/explore',query:query.value?{q:query.value}:{}})}function keys(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open()}}onMounted(()=>window.addEventListener('keydown',keys));onUnmounted(()=>window.removeEventListener('keydown',keys))
</script>
<template><button class="command-trigger" aria-label="打开植物快捷搜索" @click="open"><UiIcon name="search" :size="17"/><span>搜索植物</span><kbd>⌘ K</kbd></button><dialog ref="modal" class="command-dialog" aria-labelledby="command-title"><header><span id="command-title">在植序中探索</span><button class="vx-icon-button" aria-label="关闭快捷搜索" @click="modal?.close()"><UiIcon name="close"/></button></header><form @submit.prevent="submit"><UiIcon name="search"/><input v-model="query" aria-label="快捷搜索植物名称" placeholder="中文名、学名或科属…" autofocus/><button class="vx-button">搜索</button></form><p>试试 Ginkgo、Camellia 或银杏。只查询允许公开的真实目录。</p><footer><kbd>Esc</kbd> 关闭 <span>名称 · 来源 · 研究关系</span></footer></dialog></template>
